const ctx = $('Prepare 62 Intent Classifier Context').first().json || {};
const catalog = Array.isArray(ctx.intent_catalog) ? ctx.intent_catalog : [];
const byName = new Map(catalog.map(r=>[String(r.spm_intent||'').trim(),r]));
const clean=v=>String(v??'').trim();
function parse(v){
 if(v && typeof v==='object' && !Array.isArray(v)) return v;
 let t=clean(v).replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,'').trim();
 try{return JSON.parse(t)}catch{}
 const a=t.indexOf('{'),b=t.lastIndexOf('}');
 if(a>=0&&b>a){try{return JSON.parse(t.slice(a,b+1))}catch{}}
 return {};
}
const raw=parse($json.output ?? $json.text ?? $json.response ?? $json);
let primary=clean(raw.spm_intent || raw.primary_intent);
let secondary=clean(raw.secondary_spm_intent || raw.secondary_intent);
let confidence=Number(raw.confidence);
if(!Number.isFinite(confidence)||confidence<0||confidence>1) confidence=0;
const ambiguous=raw.ambiguous===true || clean(raw.ambiguous).toLowerCase()==='true';
const language=['ar','en','fr'].includes(clean(raw.language).toLowerCase()) ? clean(raw.language).toLowerCase() : (ctx.language_hint||'');
const matched=byName.get(primary);
const validIntent=Boolean(matched);
if(!validIntent){ primary='out_of_scope'; }
const authoritative=byName.get(primary) || {spm_intent:'out_of_scope',required_entities:[],source_gate:'APPROVED_KB_OR_LOGIC',risk_tier:'A',sales_stage:'none',min_confidence:0.85};
if(!byName.has(secondary) || secondary===primary) secondary='';
const threshold=Number.isFinite(Number(authoritative.min_confidence)) ? Number(authoritative.min_confidence) : 0.85;
let route='direct';
if(!validIntent || confidence<0.60) route='fallback';
else if(ambiguous || confidence<threshold) route='clarify';
const direct=route==='direct';
const result={
 schema:'SPM_CLASSIFIER_OUTPUT_V2',
 spm_intent:primary,
 secondary_spm_intent:secondary,
 confidence,
 threshold,
 ambiguous: ambiguous || !validIntent,
 required_entities:Array.isArray(authoritative.required_entities)?authoritative.required_entities:[],
 source_gate:clean(authoritative.source_gate),
 risk_tier:clean(authoritative.risk_tier),
 sales_stage:clean(authoritative.sales_stage),
 language,
 rationale_code:clean(raw.rationale_code) || (validIntent?'MODEL_CLASSIFICATION':'INVALID_MODEL_INTENT_RECOVERED'),
 intent_valid:validIntent,
 classifier_gate_passed:direct
};
const state={...(ctx.sales_state||{})};
state.classifier={...(state.classifier||{}),...result};
return [{json:{...ctx,sales_state:state,classification:result,classifier_route:route,classifier_gate_passed:direct,customer_clarification_required:route!=='direct',irreversible_action_allowed:false,classifier_validation_errors:validIntent?[]:['MODEL_INTENT_NOT_IN_ACTIVE_CATALOG']}}];

