const j=$input.first().json;
const state=j.sales_state||{};
const contract={schema:'SPM_NEXT_BEST_ACTION_V1',stages:['none','discovery','need','consideration','pricing','trial','scheduling','conversion','objection','nurturing','support','recovery'],override_precedence:['opt_out','support','human_handoff','recovery','sales_journey'],question_policy:'ask one purposeful missing-field question; never re-ask known data'};
