return [{json:{...j,journey_contract:contract,journey_decision:decision}}];

const j=$input.first().json;
const allowed=['APPROVED_KB_OR_LOGIC','APPROVED_CURRICULUM_SOURCE','PACKAGES_LIVE_CONFIG','AUTHORIZED_OFFER_REQUIRED','MARKET_PAYMENT_CONFIG','PAYMENT_LIVE','POLICY_AND_LIVE_STATE','VERIFIED_TEACHER_OR_POLICY','SCHEDULING_LIVE','CRM_VALIDATION'];
const gate=j.classification?.source_gate||null;
const result={gate,allowed_gates:allowed,can_answer:false,can_execute:false,source_refs:[],reason_code:gate?'WU91_SOURCE_NOT_CONNECTED':'CLASSIFICATION_NOT_READY',status:'WU91_NOT_IMPLEMENTED'};
