const j=$input.first().json;
const contract={
 schema:'SPM_SALES_AGENT_OUTPUT_V1',
 role:'consultative_sales_agent_not_faq_bot',
 fields:['answer_text','purpose','recommendation','purposeful_question','proposed_action','action_requires_gateway','claims_source_refs','handoff_requested','stop_nurture'],
 behavior:['answer_first','acknowledge_context','ask_one_purposeful_question','do_not_repeat_known_fields','no_pressure','no_unsupported_promise'],
 hard_boundary:'Agent may propose actions but cannot directly perform irreversible business actions.'
};
const output={answer_text:'WU87 architecture test reached the Sales Agent contract. The sales model is intentionally not connected yet.',purpose:'architecture_test',recommendation:null,purposeful_question:null,proposed_action:'none',action_requires_gateway:false,claims_source_refs:[],handoff_requested:false,stop_nurture:false,status:'WU92_NOT_IMPLEMENTED'};
return [{json:{...j,sales_agent_contract:contract,sales_agent_output:output}}];

const j=$input.first().json;
const requested=String(j.sales_agent_output?.proposed_action||'none');
const irreversible=['lead_upsert','booking_create','booking_change','payment_action','human_handoff_create','contact_update','opt_out_write'];
const result={requested_action:requested,executed:false,status:'NOOP_WU87',business_reference:null,reason_code:'ACTION_GATEWAY_SKELETON_ONLY',irreversible_action:false};
if (irreversible.includes(requested)) result.irreversible_action=true;
return [{json:{...j,action_gateway_contract:{schema:'SPM_ACTION_GATEWAY_V1',rule:'all irreversible actions require deterministic validation + explicit tool success before success may be reported',allowed_in_wu87:['none']},action_result:result}}];
